import gurobipy as gp
from gurobipy import GRB
demands = {}
supplies = {}
costs = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('customer_demand.csv'):
        cust = vals['customer']
        demand = float(vals['demand'])
        if cust in demands:
            raise ValueError(f'Duplicate demand for {cust}')
        demands[cust] = demand
    elif src.endswith('supply_capacity.csv'):
        wh = vals['Unnamed: 0']
        cap = float(vals['supply_capacity'])
        if wh in supplies:
            raise ValueError(f'Duplicate supply for {wh}')
        supplies[wh] = cap
    elif src.endswith('transportation_costs.csv'):
        wh = vals['Unnamed: 0']
        if wh in costs:
            raise ValueError(f'Duplicate cost row for {wh}')
        costs[wh] = {}
        for k, v in vals.items():
            if k == 'Unnamed: 0':
                continue
            costs[wh][k] = float(v)
warehouses = sorted(supplies.keys())
stores = sorted(demands.keys())
for i in warehouses:
    if i not in costs:
        raise ValueError(f'Missing cost row for warehouse {i}')
    for j in stores:
        if j not in costs[i]:
            raise ValueError(f'Missing cost for warehouse {i}, store {j}')
m = gp.Model('Transportation')
x_vars = m.addVars(warehouses, stores, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((costs[i][j] * x_vars[i, j] for i in warehouses for j in stores)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in warehouses)) == demands[j] for j in stores), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in stores)) <= supplies[i] for i in warehouses), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')